#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x1, y1, x2, y2, x3, y3;
    cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;

    double slope1 = (y2 - y1) / (x2 - x1);
    double slope2 = (y3 - y2) / (x3 - x2);

    if (slope1 == slope2) {
        cout << "The three points lie on the same line." << endl;
        return 0;
    }

    double a = (y2 - y1) / (x2 - x1) - (y3 - y2) / (x3 - x2);
